    &lt;name&gt;
      &lt;text&gt;Expand a product (form-sensitive)&lt;/text&gt;
    &lt;/name&gt;
    &lt;questiontext format="html"&gt;
      &lt;text&gt;&lt;p&gt;Expand and collect like terms: \((x+{@a@})(x+{@b@})\).&lt;/p&gt;&lt;p&gt;Give your answer as a polynomial in \(x\). [[input:ans]] [[validation:ans]] [[feedback:prt1]]&lt;/p&gt;&lt;/text&gt;
    &lt;/questiontext&gt;
    &lt;generalfeedback format="html"&gt;
      &lt;text&gt;&lt;p&gt;Multiply each term and collect: \(x^2+({@a@}+{@b@})x+{@a@}\cdot{@b@}={@ta@}\).&lt;/p&gt;&lt;p&gt;A factored expression has the same value, but this task asks for expanded form.&lt;/p&gt;&lt;/text&gt;
    &lt;/generalfeedback&gt;
    &lt;defaultgrade&gt;1&lt;/defaultgrade&gt;
    &lt;penalty&gt;0.1&lt;/penalty&gt;
    &lt;hidden&gt;0&lt;/hidden&gt;
    &lt;idnumber/&gt;
    &lt;stackversion&gt;
      &lt;text&gt;2021072200&lt;/text&gt;
    &lt;/stackversion&gt;
    &lt;questionvariables&gt;
      &lt;text&gt;a:rand(4)+2;
b:rand(3)+2;
ta:x^2+(a+b)*x+a*b;&lt;/text&gt;
    &lt;/questionvariables&gt;
    &lt;specificfeedback format="html"&gt;
      &lt;text&gt;&lt;p&gt;[[feedback:prt1]]&lt;/p&gt;&lt;/text&gt;
    &lt;/specificfeedback&gt;
    &lt;questionnote format="moodle_auto_format"&gt;
      &lt;text&gt;Expansion: (x+a)(x+b) = ta&lt;/text&gt;
    &lt;/questionnote&gt;
    &lt;questiondescription format="moodle_auto_format"&gt;
      &lt;text/&gt;
    &lt;/questiondescription&gt;
    &lt;questionsimplify&gt;1&lt;/questionsimplify&gt;
    &lt;assumepositive&gt;0&lt;/assumepositive&gt;
    &lt;assumereal&gt;0&lt;/assumereal&gt;
    &lt;scientificnotation&gt;*10&lt;/scientificnotation&gt;
    &lt;multiplicationsign&gt;none&lt;/multiplicationsign&gt;
    &lt;sqrtsign&gt;1&lt;/sqrtsign&gt;
    &lt;complexno&gt;i&lt;/complexno&gt;
    &lt;inversetrig&gt;cos-1&lt;/inversetrig&gt;
    &lt;logicsymbol&gt;lang&lt;/logicsymbol&gt;
    &lt;matrixparens&gt;[&lt;/matrixparens&gt;
    &lt;isbroken&gt;0&lt;/isbroken&gt;
    &lt;variantsselectionseed/&gt;
    &lt;input&gt;
      &lt;name&gt;ans&lt;/name&gt;
      &lt;type&gt;algebraic&lt;/type&gt;
      &lt;tans&gt;ta&lt;/tans&gt;
      &lt;boxsize&gt;18&lt;/boxsize&gt;
      &lt;strictsyntax&gt;1&lt;/strictsyntax&gt;
      &lt;insertstars&gt;1&lt;/insertstars&gt;
      &lt;syntaxhint/&gt;
      &lt;syntaxattribute&gt;0&lt;/syntaxattribute&gt;
      &lt;forbidwords/&gt;
      &lt;allowwords/&gt;
      &lt;forbidfloat&gt;1&lt;/forbidfloat&gt;
      &lt;requirelowestterms&gt;0&lt;/requirelowestterms&gt;
      &lt;checkanswertype&gt;1&lt;/checkanswertype&gt;
      &lt;mustverify&gt;1&lt;/mustverify&gt;
      &lt;showvalidation&gt;1&lt;/showvalidation&gt;
      &lt;options/&gt;
    &lt;/input&gt;
    &lt;prt&gt;
      &lt;name&gt;prt1&lt;/name&gt;
      &lt;value&gt;1.0000000&lt;/value&gt;
      &lt;autosimplify&gt;0&lt;/autosimplify&gt;
      &lt;feedbackstyle&gt;1&lt;/feedbackstyle&gt;
      &lt;feedbackvariables&gt;
        &lt;text/&gt;
      &lt;/feedbackvariables&gt;
      &lt;node&gt;
        &lt;name&gt;0&lt;/name&gt;
        &lt;description/&gt;
        &lt;answertest&gt;EqualComAss&lt;/answertest&gt;
        &lt;sans&gt;ans&lt;/sans&gt;
        &lt;tans&gt;ta&lt;/tans&gt;
        &lt;testoptions/&gt;
        &lt;quiet&gt;0&lt;/quiet&gt;
        &lt;truescoremode&gt;=&lt;/truescoremode&gt;
        &lt;truescore&gt;1.0000000&lt;/truescore&gt;
        &lt;truepenalty/&gt;
        &lt;truenextnode&gt;-1&lt;/truenextnode&gt;
        &lt;trueanswernote&gt;prt1-0-T&lt;/trueanswernote&gt;
        &lt;truefeedback format="html"&gt;
          &lt;text&gt;&lt;p&gt;Correct: the expression is expanded and collected.&lt;/p&gt;&lt;/text&gt;
        &lt;/truefeedback&gt;
        &lt;falsescoremode&gt;=&lt;/falsescoremode&gt;
        &lt;falsescore&gt;0.0000000&lt;/falsescore&gt;
        &lt;falsepenalty/&gt;
        &lt;falsenextnode&gt;1&lt;/falsenextnode&gt;
        &lt;falseanswernote&gt;prt1-0-F&lt;/falseanswernote&gt;
        &lt;falsefeedback format="html"&gt;
          &lt;text/&gt;
        &lt;/falsefeedback&gt;
      &lt;/node&gt;
      &lt;node&gt;
        &lt;name&gt;1&lt;/name&gt;
        &lt;description/&gt;
        &lt;answertest&gt;AlgEquiv&lt;/answertest&gt;
        &lt;sans&gt;ans&lt;/sans&gt;
        &lt;tans&gt;ta&lt;/tans&gt;
        &lt;testoptions/&gt;
        &lt;quiet&gt;0&lt;/quiet&gt;
        &lt;truescoremode&gt;=&lt;/truescoremode&gt;
        &lt;truescore&gt;0.5000000&lt;/truescore&gt;
        &lt;truepenalty/&gt;
        &lt;truenextnode&gt;-1&lt;/truenextnode&gt;
        &lt;trueanswernote&gt;prt1-1-T&lt;/trueanswernote&gt;
        &lt;truefeedback format="html"&gt;
          &lt;text&gt;&lt;p&gt;This is equivalent, but expand the product and collect like terms for full credit.&lt;/p&gt;&lt;/text&gt;
        &lt;/truefeedback&gt;
        &lt;falsescoremode&gt;=&lt;/falsescoremode&gt;
        &lt;falsescore&gt;0.0000000&lt;/falsescore&gt;
        &lt;falsepenalty/&gt;
        &lt;falsenextnode&gt;-1&lt;/falsenextnode&gt;
        &lt;falseanswernote&gt;prt1-1-F&lt;/falseanswernote&gt;
        &lt;falsefeedback format="html"&gt;
          &lt;text&gt;&lt;p&gt;Check the middle term and constant term when you multiply the binomials.&lt;/p&gt;&lt;/text&gt;
